491	/*
492	 * Compact conversation list (DESIGN.md "Conversation Row"): 36px rows on 12px
493	 * type in two weights, separated by rhythm alone (no per-row dividers). The
494	 * row highlight is inset 6px from both pane edges; the 44px left gutter holds
495	 * the selection checkbox and the read marker, so sender names, date captions
496	 * and the split tabs share the 50px content inset.
497	 */
498	.inbox-scroll {
499	  list-style: none;
500	  margin: 0;
501	  padding: 0;
502	  overflow-y: auto;
503	  height: 100%;
504	  min-height: 0;
505	  /* Row columns size from the list width (cqi), never from one row's content. */
506	  container-type: inline-size;
