518	  display: flex;
519	  align-items: center;
520	  gap: 12px;
521	  min-height: 36px;
522	  margin: 0 6px;
523	  padding: 0 18px 0 44px;
524	  font-size: 0.75rem;
525	  line-height: 1.35;
526	  color: var(--text-primary);
527	  cursor: pointer;
528	  /* Anchors the gutter controls and the row action disclosure panel. */
529	  position: relative;
530	}
