mount = r'''
await js(`(async () => {
  const vueUrl = performance.getEntriesByType('resource').map((x) => x.name).find((n) => n.includes('/node_modules/.vite/deps/vue.js'));
  const { createApp } = await import(vueUrl);
  const { default: App } = await import('/src/App.vue');
  const { createBrowserFakeMailClient } = await import('/src/lib/ipc/browser-fake.ts');
  const root = document.querySelector('#app');
  root.__vue_app__?.unmount();
  root.innerHTML = '';
  const fake = createBrowserFakeMailClient();
  fake.controls.setAccount({ mode: 'gmail', connection: 'connected', emailAddress: 'review@example.test', mutationAccess: 'enabled', coverageLimit: 100 });
  const d = new Date(); const at = (days, h, m) => { const x = new Date(d.getFullYear(), d.getMonth(), d.getDate() - days, h, m); return x.toISOString(); };
  const dates = { 'conv-01': at(0, 9, 12), 'conv-02': at(0, 8, 0), 'conv-03': at(1, 17, 40), 'conv-04': at(1, 11, 5), 'conv-05': at(9, 10, 0) };
  const client = { ...fake, listConversations: async (...a) => { const s = await fake.listConversations(...a); return { ...s, conversations: s.conversations.map((r) => dates[r.ref.conversationId] ? { ...r, lastMessageAt: dates[r.ref.conversationId] } : r) }; } };
  createApp(App, { client, mode: 'browser-preview' }).mount(root);
})()`);
for (let i = 0; i < 50; i++) { if (await js("!!document.querySelector('.inbox-row')")) break; await sleep(200); }
await sleep(600);
